function StatusPill({ status }) {
  const map = {
    approved: "bg-emerald-50 text-emerald-700 border-emerald-200",
    pending: "bg-amber-50 text-amber-700 border-amber-200",
    rejected: "bg-rose-50 text-rose-700 border-rose-200",
    paid: "bg-emerald-50 text-emerald-700 border-emerald-200",
    "not paid": "bg-rose-50 text-rose-700 border-rose-200",
  };
  return (
    <span className={`text-xs px-2 py-0.5 rounded-full border ${map[status] || "bg-stone-100 text-stone-600 border-stone-200"}`}>
      {status}
    </span>
  );
}

function BottomNav({ tab, setTab }) {
  const items = [
    { id: "home", label: "Home", icon: Home },
    { id: "batches", label: "Batches", icon: BookOpen },
    { id: "gallery", label: "Gallery", icon: Images },
    { id: "profile", label: "Profile", icon: User },
  ];
  return (
    <div className="border-t border-stone-200 bg-stone-50 flex justify-around py-2 sticky bottom-0">
      {items.map((it) => {
        const Icon = it.icon;
        const active = tab === it.id;
        return (
          <button
            key={it.id}
            onClick={() => setTab(it.id)}
            className={`flex flex-col items-center gap-0.5 px-2 py-1 ${active ? "text-violet-700" : "text-stone-400"}`}
          >
            <Icon size={20} strokeWidth={active ? 2.4 : 1.8} />
            <span className="text-[10px] font-sans">{it.label}</span>
          </button>
        );
      })}
    </div>
  );
}

// ---------- App ----------
export default function App() {
  const [screen, setScreen] = useState("welcome"); // welcome | phone | otp | profileSetup | teacherEntry | teacherPhone | teacherOtp | teacherPasscode | app
  const [role, setRole] = useState(null); // "student" | "teacher"
  const [tab, setTab] = useState("home");

  const [phone, setPhone] = useState("");
  const [otp, setOtp] = useState("");
  const [otpError, setOtpError] = useState("");
  const [resendTimer, setResendTimer] = useState(0);

  const [teacherPasscodeInput, setTeacherPasscodeInput] = useState("");
  const [teacherPasscodeError, setTeacherPasscodeError] = useState("");

  const [student, setStudent] = useState({ name: "", photo: null, cls: "", board: "" });
  const fileInputRef = useRef(null);

  const [enrollments, setEnrollments] = useState([]); // {batchId, status}
  const [selectedBatch, setSelectedBatch] = useState(null);
  const [openBatchClass, setOpenBatchClass] = useState(null);
  const [workspaceBatchId, setWorkspaceBatchId] = useState(null); // which batch's homework/community is open
  const [galleryPhoto, setGalleryPhoto] = useState(null);
  const [galleryPhotos, setGalleryPhotos] = useState(GALLERY_PHOTOS);

  const [homework, setHomework] = useState([
    { id: 1, batchId: "10-CBSE-A", subject: "English", title: "Unseen Passage Practice — Set 4", desc: "Complete Q1-Q5, focus on inference-based answers.", date: "29 Aug 2026", type: "PDF" },
    { id: 2, batchId: "10-CBSE-A", subject: "English", title: "Grammar: Reported Speech", desc: "Worksheet + 10 transformation sentences.", date: "26 Aug 2026", type: "PDF" },
    { id: 3, batchId: "10-CBSE-A", subject: "English", title: "Reference video — Narration rules", desc: "Watch before Thursday's class.", date: "24 Aug 2026", type: "Link" },
  ]);

  const [classVideos, setClassVideos] = useState({
    "10-CBSE-A": [
      { id: 1, title: "Unseen Passage — comprehension strategy", date: "02 Sep 2026", duration: "38 min" },
      { id: 2, title: "Reported Speech — full walkthrough", date: "29 Aug 2026", duration: "45 min" },
      { id: 3, title: "Poetry: figures of speech recap", date: "22 Aug 2026", duration: "31 min" },
    ],
  });

  const [testResults, setTestResults] = useState({
    "10-CBSE-A": [
      { id: 1, testName: "Diagnostic Test 1", date: "16 Aug 2026", score: 42, max: 50 },
      { id: 2, testName: "Grammar Unit Test", date: "24 Aug 2026", score: 27, max: 30 },
    ],
  });

  const [messages, setMessages] = useState({
    "10-CBSE-A": [
      { id: 1, from: "teacher", name: "Partha Sir", text: "Welcome to Batch A! Diagnostic test this Saturday, 10 AM sharp.", pinned: true },
      { id: 2, from: "student", name: "Ritika", text: "Sir, will it cover reported speech too?" },
      { id: 3, from: "teacher", name: "Partha Sir", text: "Yes — grammar + one unseen passage." },
    ],
  });
  const [draft, setDraft] = useState("");

  const [payment, setPayment] = useState({
    monthlyFee: 2500,
    status: "not paid",
    month: "September",
    year: 2026,
    history: [
      { id: "TXN10245", month: "August", year: 2026, amount: 2500, date: "03 Aug 2026", time: "11:14 AM", status: "paid" },
      { id: "TXN10198", month: "July", year: 2026, amount: 2500, date: "04 Jul 2026", time: "6:02 PM", status: "paid" },
    ],
  });
  const [showReceipt, setShowReceipt] = useState(null);

  const approvedBatches = enrollments.filter((e) => e.status === "approved").map((e) => e.batchId);

  // ---------- Cross-device sync (Firebase Firestore) ----------
  // This replaces Claude's artifact-only storage with a real backend, so
  // syncing works once this app is compiled and installed on real phones —
  // not just inside Claude. Updates arrive in real time (no polling delay).
  function pushShared(updates) {
    const next = {
      enrollments: updates.enrollments ?? enrollments,
      homework: updates.homework ?? homework,
      classVideos: updates.classVideos ?? classVideos,
      testResults: updates.testResults ?? testResults,
      messages: updates.messages ?? messages,
      payment: updates.payment ?? payment,
      galleryPhotos: updates.galleryPhotos ?? galleryPhotos,
      student: updates.student ?? student,
    };
    if ("enrollments" in updates) setEnrollments(updates.enrollments);
    if ("homework" in updates) setHomework(updates.homework);
    if ("classVideos" in updates) setClassVideos(updates.classVideos);
    if ("testResults" in updates) setTestResults(updates.testResults);
    if ("messages" in updates) setMessages(updates.messages);
    if ("payment" in updates) setPayment(updates.payment);
    if ("galleryPhotos" in updates) setGalleryPhotos(updates.galleryPhotos);
    if ("student" in updates) setStudent(updates.student);
    setDoc(sharedDocRef, next, { merge: true }).catch((e) => {
      console.warn("Firestore write failed — check firebaseConfig and Firestore rules.", e);
    });
  }

  // Subscribe once we're past login. onSnapshot pushes updates the instant
  // the other device (teacher or student) writes — no polling needed.
  useEffect(() => {
    if (screen !== "app") return;
    const unsubscribe = onSnapshot(
      sharedDocRef,
      (snap) => {
        if (!snap.exists()) return;
        const remote = snap.data();
        if (remote.enrollments) setEnrollments(remote.enrollments);
        if (remote.homework) setHomework(remote.homework);
        if (remote.classVideos) setClassVideos(remote.classVideos);
        if (remote.testResults) setTestResults(remote.testResults);
        if (remote.messages) setMessages(remote.messages);
        if (remote.payment) setPayment(remote.payment);
        if (remote.galleryPhotos) setGalleryPhotos(remote.galleryPhotos);
        if (remote.student && role === "teacher") setStudent(remote.student);
      },
      (err) => {
        console.warn("Firestore listen failed — check firebaseConfig and Firestore rules.", err);
      }
    );
    return () => unsubscribe();
  }, [screen, role]);


  // ---------- handlers ----------
  function sendOtp(nextScreen = "otp") {
    setScreen(nextScreen);
    setOtpError("");
    setResendTimer(30);
    const t = setInterval(() => {
      setResendTimer((s) => {
        if (s <= 1) { clearInterval(t); return 0; }
        return s - 1;
      });
    }, 1000);
  }

  function verifyOtp() {
    if (otp !== "123456") {
      if (otp.length < 6) {
        setOtpError("Enter the 6-digit code sent to your phone.");
      } else {
        setOtpError("That code doesn't match. Use 123456 for this demo, or resend.");
      }
      return;
    }
    setOtpError("");
    setRole("student");
    setScreen(student.name ? "app" : "profileSetup");
  }

  function verifyTeacherOtp() {
    if (otp !== "123456") {
      if (otp.length < 6) {
        setOtpError("Enter the 6-digit code sent to your phone.");
      } else {
        setOtpError("That code doesn't match. Use 123456 for this demo, or resend.");
      }
      return;
    }
    setOtpError("");
    setRole("teacher");
    setScreen("app");
    setTab("home");
  }

  function submitTeacherPhone() {
    if (phone !== TEACHER_PHONE) {
      setOtpError("");
      setTeacherPasscodeError("This number isn't registered for teacher access.");
      return;
    }
    setTeacherPasscodeError("");
    sendOtp("teacherOtp");
  }

  function submitTeacherPasscode() {
    if (teacherPasscodeInput === TEACHER_PASSCODE) {
      setTeacherPasscodeError("");
      setTeacherPasscodeInput("");
      setRole("teacher");
      setScreen("app");
      setTab("home");
    } else {
      setTeacherPasscodeError("Incorrect passcode.");
    }
  }

  function logout() {
    setRole(null);
    setScreen("welcome");
    setTab("home");
    setSelectedBatch(null);
    setWorkspaceBatchId(null);
    setPhone("");
    setOtp("");
    setTeacherPasscodeInput("");
    setTeacherPasscodeError("");
  }

  function handlePhotoChange(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setStudent((s) => ({ ...s, photo: reader.result }));
    reader.readAsDataURL(file);
  }

  function completeProfile() {
    if (!student.name || !student.cls || !student.board) return;
    pushShared({ student });
    setScreen("app");
    setTab("home");
  }

  function requestEnrollment(batch) {
    if (enrollments.some((e) => e.batchId === batch.id)) return;
    pushShared({ enrollments: [...enrollments, { batchId: batch.id, status: "pending" }] });
    // a real teacher now approves/rejects this from the Teacher Dashboard
  }

  function statusFor(batchId) {
    return enrollments.find((e) => e.batchId === batchId)?.status || null;
  }

  // ---------- Teacher-side handlers (mutate the same shared state the student view reads) ----------
  function approveEnrollment(batchId) {
    pushShared({ enrollments: enrollments.map((e) => (e.batchId === batchId ? { ...e, status: "approved" } : e)) });
  }
  function rejectEnrollment(batchId) {
    pushShared({ enrollments: enrollments.map((e) => (e.batchId === batchId ? { ...e, status: "rejected" } : e)) });
  }
  function addHomeworkItem(item) {
    pushShared({ homework: [{ ...item, id: Date.now() }, ...homework] });
  }
  function deleteHomeworkItem(id) {
    pushShared({ homework: homework.filter((h) => h.id !== id) });
  }
  function addClassVideo(batchId, video) {
    pushShared({ classVideos: { ...classVideos, [batchId]: [{ ...video, id: Date.now() }, ...(classVideos[batchId] || [])] } });
  }
  function deleteClassVideo(batchId, id) {
    pushShared({ classVideos: { ...classVideos, [batchId]: (classVideos[batchId] || []).filter((v) => v.id !== id) } });
  }
  function addTestResult(batchId, result) {
    pushShared({ testResults: { ...testResults, [batchId]: [{ ...result, id: Date.now() }, ...(testResults[batchId] || [])] } });
  }
  function deleteTestResult(batchId, id) {
    pushShared({ testResults: { ...testResults, [batchId]: (testResults[batchId] || []).filter((r) => r.id !== id) } });
  }
  function teacherSendMessage(batchId, text) {
    if (!text.trim()) return;
    pushShared({
      messages: {
        ...messages,
        [batchId]: [...(messages[batchId] || []), { id: Date.now(), from: "teacher", name: TEACHER.name, text: text.trim() }],
      },
    });
  }
  function deleteMessage(batchId, id) {
    pushShared({ messages: { ...messages, [batchId]: (messages[batchId] || []).filter((m) => m.id !== id) } });
  }
  function togglePinMessage(batchId, id) {
    pushShared({
      messages: {
        ...messages,
        [batchId]: (messages[batchId] || []).map((m) => (m.id === id ? { ...m, pinned: !m.pinned } : m)),
      },
    });
  }
  function addGalleryPhoto(dataUrl) {
    pushShared({ galleryPhotos: [...galleryPhotos, { src: dataUrl }] });
  }

  function openMyBatches() {
    if (approvedBatches.length === 0) {
      // nothing enrolled yet — only place browsing the full catalog makes sense
      setSelectedBatch(null);
      setTab("batches");
    } else if (approvedBatches.length === 1) {
      // straight into that batch's hub, no detour through the catalog
      const batch = CATALOG.find((b) => b.id === approvedBatches[0]);
      setSelectedBatch(batch);
      setTab("batches");
    } else {
      // more than one — a short list of just their enrolled batches
      setSelectedBatch(null);
      setTab("mybatches");
    }
  }

  function sendMessage(batchId) {
    if (!draft.trim()) return;
    pushShared({
      messages: {
        ...messages,
        [batchId]: [...(messages[batchId] || []), { id: Date.now(), from: "student", name: student.name || "You", text: draft.trim() }],
      },
    });
    setDraft("");
  }

  function payNow() {
    const txn = "TXN" + Math.floor(10000 + Math.random() * 89999);
    const now = new Date();
    const receipt = {
      id: txn,
      month: payment.month,
      year: payment.year,
      amount: payment.monthlyFee,
      date: now.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }),
      time: now.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }),
      status: "paid",
    };
    pushShared({ payment: { ...payment, status: "paid", history: [receipt, ...payment.history] } });
    setShowReceipt(receipt);
  }

  // ================= SCREENS =================

  if (screen === "welcome") {
    return (
      <Frame>
        <div className="flex-1 flex flex-col items-center justify-center px-8 text-center">
          <Mark size={72} />
          <h1 className="font-serif text-3xl text-stone-900 mt-5">Quest Question Quench</h1>
          <Underline />
          <p className="font-serif italic text-stone-500 mt-3 text-sm leading-relaxed">
            Where English gets enlightened
          </p>
          <p className="text-stone-400 text-xs mt-1">ICSE · ISC · CBSE · TBSE &nbsp;·&nbsp; Class 8–12</p>
        </div>
        <div className="px-6 pb-10 flex flex-col gap-3">
          <button
            onClick={() => setScreen("phone")}
            className="bg-violet-800 text-stone-50 font-sans font-medium py-3.5 rounded-md"
          >
            Continue as student
          </button>
          <button onClick={() => setScreen("teacherEntry")} className="text-stone-400 text-sm py-2 font-sans">
            Staff access
          </button>
        </div>
      </Frame>
    );
  }

  if (screen === "teacherEntry") {
    return (
      <Frame>
        <TopBar title="Teacher login" onBack={() => setScreen("welcome")} />
        <div className="px-6 pt-8 flex-1 flex flex-col items-center text-center">
          <Lock size={28} className="text-violet-300 mb-3" />
          <p className="text-stone-500 text-sm leading-relaxed">
            This area is for authorized teachers only. Sign in with your registered phone number, or use your passcode instead.
          </p>
        </div>
        <div className="px-6 pb-10 flex flex-col gap-3">
          <button
            onClick={() => { setTeacherPasscodeError(""); setPhone(""); setScreen("teacherPhone"); }}
            className="bg-violet-800 text-stone-50 font-sans font-medium py-3.5 rounded-md"
          >
            Log in with phone number
          </button>
          <button
            onClick={() => { setTeacherPasscodeError(""); setTeacherPasscodeInput(""); setScreen("teacherPasscode"); }}
            className="border border-stone-300 text-stone-700 font-sans font-medium py-3.5 rounded-md"
          >
            Other login option — use passcode
          </button>
        </div>
      </Frame>
    );
  }

  if (screen === "teacherPhone") {
    return (
      <Frame>
        <TopBar title="Teacher login" onBack={() => setScreen("teacherEntry")} />
        <div className="px-6 pt-6 flex-1">
          <p className="text-stone-500 text-sm mb-6">Enter your registered teacher phone number.</p>
          <label className="text-xs text-stone-400 font-sans">Mobile number</label>
          <div className="flex items-center border-b border-stone-300 py-2 mt-1 gap-2">
            <Phone size={16} className="text-stone-400" />
            <span className="text-stone-500 text-sm">+91</span>
            <input
              value={phone}
              onChange={(e) => { setPhone(e.target.value.replace(/\D/g, "").slice(0, 10)); setTeacherPasscodeError(""); }}
              placeholder="98765 43210"
              className="flex-1 outline-none font-sans text-stone-900 bg-transparent"
              inputMode="numeric"
            />
          </div>
          {teacherPasscodeError && <p className="text-rose-600 text-xs mt-3">{teacherPasscodeError}</p>}
        </div>
        <div className="px-6 pb-10">
          <button
            disabled={phone.length !== 10}
            onClick={submitTeacherPhone}
            className={`w-full py-3.5 rounded-md font-sans font-medium ${phone.length === 10 ? "bg-violet-800 text-stone-50" : "bg-stone-200 text-stone-400"}`}
          >
            Send code
          </button>
        </div>
      </Frame>
    );
  }

  if (screen === "teacherOtp") {
    return (
      <Frame>
        <TopBar title="Verify your number" onBack={() => setScreen("teacherPhone")} />
        <div className="px-6 pt-6 flex-1">
          <p className="text-stone-500 text-sm mb-1">Enter the 6-digit code sent to +91 {phone}.</p>
          <p className="text-stone-300 text-xs mb-6">(Demo code: 123456)</p>
          <input
            value={otp}
            onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
            placeholder="••••••"
            className="w-full text-center tracking-[0.6em] text-2xl border-b border-stone-300 py-2 outline-none font-sans bg-transparent"
            inputMode="numeric"
          />
          {otpError && <p className="text-rose-600 text-xs mt-3">{otpError}</p>}
          <div className="mt-5 text-sm font-sans">
            {resendTimer > 0 ? (
              <span className="text-stone-400">Resend code in {resendTimer}s</span>
            ) : (
              <button onClick={() => sendOtp("teacherOtp")} className="text-violet-700">Resend code</button>
            )}
          </div>
        </div>
        <div className="px-6 pb-10">
          <button
            disabled={otp.length !== 6}
            onClick={verifyTeacherOtp}
            className={`w-full py-3.5 rounded-md font-sans font-medium ${otp.length === 6 ? "bg-violet-800 text-stone-50" : "bg-stone-200 text-stone-400"}`}
          >
            Verify &amp; continue
          </button>
        </div>
      </Frame>
    );
  }

  if (screen === "teacherPasscode") {
    return (
      <Frame>
        <TopBar title="Teacher passcode" onBack={() => setScreen("teacherEntry")} />
        <div className="px-6 pt-6 flex-1">
          <p className="text-stone-500 text-sm mb-6">Enter your special teacher passcode to continue.</p>
          <input
            type="password"
            value={teacherPasscodeInput}
            onChange={(e) => { setTeacherPasscodeInput(e.target.value); setTeacherPasscodeError(""); }}
            placeholder="Passcode"
            className="w-full border-b border-stone-300 py-2 outline-none font-sans bg-transparent tracking-widest"
          />
          {teacherPasscodeError && <p className="text-rose-600 text-xs mt-3">{teacherPasscodeError}</p>}
        </div>
        <div className="px-6 pb-10">
          <button
            disabled={!teacherPasscodeInput}
            onClick={submitTeacherPasscode}
            className={`w-full py-3.5 rounded-md font-sans font-medium ${teacherPasscodeInput ? "bg-violet-800 text-stone-50" : "bg-stone-200 text-stone-400"}`}
          >
            Unlock Teacher Dashboard
          </button>
        </div>
      </Frame>
    );
  }

  if (screen === "phone") {
    return (
      <Frame>
        <TopBar title="Student login" onBack={() => setScreen("welcome")} />
        <div className="px-6 pt-6 flex-1">
          <p className="text-stone-500 text-sm mb-6">Enter your mobile number. We'll send a one-time code to verify it's you.</p>
          <label className="text-xs text-stone-400 font-sans">Mobile number</label>
          <div className="flex items-center border-b border-stone-300 py-2 mt-1 gap-2">
            <Phone size={16} className="text-stone-400" />
            <span className="text-stone-500 text-sm">+91</span>
            <input
              value={phone}
              onChange={(e) => setPhone(e.target.value.replace(/\D/g, "").slice(0, 10))}
              placeholder="98765 43210"
              className="flex-1 outline-none font-sans text-stone-900 bg-transparent"
              inputMode="numeric"
            />
          </div>
        </div>
        <div className="px-6 pb-10">
          <button
            disabled={phone.length !== 10}
            onClick={() => sendOtp()}
            className={`w-full py-3.5 rounded-md font-sans font-medium ${phone.length === 10 ? "bg-violet-800 text-stone-50" : "bg-stone-200 text-stone-400"}`}
          >
            Send code
          </button>
        </div>
      </Frame>
    );
  }

  if (screen === "otp") {
    return (
      <Frame>
        <TopBar title="Verify your number" onBack={() => setScreen("phone")} />
        <div className="px-6 pt-6 flex-1">
          <p className="text-stone-500 text-sm mb-1">Enter the 6-digit code sent to +91 {phone}.</p>
          <p className="text-stone-300 text-xs mb-6">(Demo code: 123456)</p>
          <input
            value={otp}
            onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
            placeholder="••••••"
            className="w-full text-center tracking-[0.6em] text-2xl border-b border-stone-300 py-2 outline-none font-sans bg-transparent"
            inputMode="numeric"
          />
          {otpError && <p className="text-rose-600 text-xs mt-3">{otpError}</p>}
          <div className="mt-5 text-sm font-sans">
            {resendTimer > 0 ? (
              <span className="text-stone-400">Resend code in {resendTimer}s</span>
            ) : (
              <button onClick={() => sendOtp()} className="text-violet-700">Resend code</button>
            )}
          </div>
        </div>
        <div className="px-6 pb-10">
          <button
            disabled={otp.length !== 6}
            onClick={verifyOtp}
            className={`w-full py-3.5 rounded-md font-sans font-medium ${otp.length === 6 ? "bg-violet-800 text-stone-50" : "bg-stone-200 text-stone-400"}`}
          >
            Verify &amp; continue
          </button>
        </div>
      </Frame>
    );
  }

  if (screen === "profileSetup") {
    return (
      <Frame>
        <TopBar title="Set up your profile" />
        <div className="px-6 pt-4 flex-1 overflow-y-auto pb-4">
          <div className="flex flex-col items-center mb-6">
            <div
              onClick={() => fileInputRef.current?.click()}
              className="w-24 h-24 rounded-full bg-violet-50 border-2 border-dashed border-violet-200 flex items-center justify-center overflow-hidden cursor-pointer"
            >
              {student.photo ? (
                <img src={student.photo} alt="Profile" className="w-full h-full object-cover" />
              ) : (
                <Camera size={26} className="text-violet-300" />
              )}
            </div>
            <input ref={fileInputRef} type="file" accept="image/*" onChange={handlePhotoChange} className="hidden" />
            <button onClick={() => fileInputRef.current?.click()} className="text-violet-700 text-xs mt-2 font-sans flex items-center gap-1">
              <Upload size={12} /> {student.photo ? "Change photo" : "Add face photo"}
            </button>
          </div>

          <label className="text-xs text-stone-400 font-sans">Full name</label>
          <input
            value={student.name}
            onChange={(e) => setStudent((s) => ({ ...s, name: e.target.value }))}
            placeholder="As per school records"
            className="w-full border-b border-stone-300 py-2 mb-5 outline-none font-sans bg-transparent"
          />

          <label className="text-xs text-stone-400 font-sans">Class</label>
          <div className="flex flex-wrap gap-2 mt-2 mb-5">
            {CLASSES.map((c) => (
              <button
                key={c}
                onClick={() => setStudent((s) => ({ ...s, cls: c }))}
                className={`px-4 py-1.5 rounded-full text-sm border font-sans ${student.cls === c ? "bg-violet-800 text-stone-50 border-violet-800" : "border-stone-300 text-stone-600"}`}
              >
                {c}
              </button>
            ))}
          </div>

          <label className="text-xs text-stone-400 font-sans">Board</label>
          <div className="flex flex-wrap gap-2 mt-2 mb-2">
            {BOARDS.map((b) => (
              <button
                key={b}
                onClick={() => setStudent((s) => ({ ...s, board: b }))}
                className={`px-4 py-1.5 rounded-full text-sm border font-sans ${student.board === b ? "bg-violet-800 text-stone-50 border-violet-800" : "border-stone-300 text-stone-600"}`}
              >
                {b}
              </button>
            ))}
          </div>
        </div>
        <div className="px-6 pb-10">
          <button
            disabled={!student.name || !student.cls || !student.board}
            onClick={completeProfile}
            className={`w-full py-3.5 rounded-md font-sans font-medium ${student.name && student.cls && student.board ? "bg-violet-800 text-stone-50" : "bg-stone-200 text-stone-400"}`}
          >
            Go to dashboard
          </button>
        </div>
      </Frame>
    );
  }

  // ---------- Main app (post login) ----------
  if (role === "teacher") {
    return (
      <Frame>
        <div className="flex-1 overflow-y-auto">
          {tab === "home" && (
            <TeacherHomeTab enrollments={enrollments} setTab={setTab} payment={payment} />
          )}
          {tab === "batches" && !selectedBatch && (
            <TeacherBatchesTab
              openBatchClass={openBatchClass}
              setOpenBatchClass={setOpenBatchClass}
              statusFor={statusFor}
              setSelectedBatch={setSelectedBatch}
            />
          )}
          {tab === "batches" && selectedBatch && (
            <TeacherBatchHub
              batch={selectedBatch}
              status={statusFor(selectedBatch.id)}
              student={student}
              onBack={() => setSelectedBatch(null)}
              onApprove={() => approveEnrollment(selectedBatch.id)}
              onReject={() => rejectEnrollment(selectedBatch.id)}
              onOpenHomework={() => { setWorkspaceBatchId(selectedBatch.id); setTab("homework"); }}
              onOpenCommunity={() => { setWorkspaceBatchId(selectedBatch.id); setTab("community"); }}
              onOpenClasses={() => { setWorkspaceBatchId(selectedBatch.id); setTab("classes"); }}
              onOpenResults={() => { setWorkspaceBatchId(selectedBatch.id); setTab("testresults"); }}
            />
          )}
          {tab === "homework" && (
            <TeacherHomeworkManage
              homework={homework}
              batchId={workspaceBatchId}
              onAdd={addHomeworkItem}
              onDelete={deleteHomeworkItem}
              onBack={() => setTab("batches")}
            />
          )}
          {tab === "community" && (
            <TeacherCommunityTab
              batchId={workspaceBatchId}
              messages={messages}
              draft={draft}
              setDraft={setDraft}
              onSend={teacherSendMessage}
              onDelete={deleteMessage}
              onTogglePin={togglePinMessage}
              onBack={() => setTab("batches")}
            />
          )}
          {tab === "classes" && (
            <TeacherClassesManage
              batchId={workspaceBatchId}
              classVideos={classVideos}
              onAdd={addClassVideo}
              onDelete={deleteClassVideo}
              onBack={() => setTab("batches")}
            />
          )}
          {tab === "testresults" && (
            <TeacherResultsManage
              batchId={workspaceBatchId}
              testResults={testResults}
              student={student}
              onAdd={addTestResult}
              onDelete={deleteTestResult}
              onBack={() => setTab("batches")}
            />
          )}
          {tab === "gallery" && (
            <TeacherGalleryTab galleryPhotos={galleryPhotos} onAdd={addGalleryPhoto} />
          )}
          {tab === "profile" && (
            <TeacherProfileTab onLogout={logout} />
          )}
          {tab === "payment" && (
            <TeacherPaymentsTab payment={payment} student={student} payNow={payNow} openReceipt={setShowReceipt} onBack={() => setTab("home")} />
          )}
        </div>
        {showReceipt && (
          <ReceiptModal receipt={showReceipt} student={student} onClose={() => setShowReceipt(null)} />
        )}
        <BottomNav
          tab={
            tab === "payment"
              ? "home"
              : ["homework", "community", "classes", "testresults"].includes(tab)
              ? "batches"
              : tab
          }
          setTab={(t) => { setSelectedBatch(null); setWorkspaceBatchId(null); setTab(t); }}
        />
      </Frame>
    );
  }

  return (
    <Frame>
      <div className="flex-1 overflow-y-auto">
        {tab === "home" && (
          <HomeTab
            student={student}
            approvedBatches={approvedBatches}
            setTab={setTab}
            setScreen={setScreen}
            payment={payment}
            onOpenMyBatches={openMyBatches}
          />
        )}
        {tab === "mybatches" && (
          <MyBatchesTab
            approvedBatches={approvedBatches}
            onSelect={(batch) => { setSelectedBatch(batch); setTab("batches"); }}
            onBack={() => setTab("home")}
          />
        )}
        {tab === "batches" && !selectedBatch && (
          <BatchesTab
            openBatchClass={openBatchClass}
            setOpenBatchClass={setOpenBatchClass}
            statusFor={statusFor}
            setSelectedBatch={setSelectedBatch}
          />
        )}
        {tab === "batches" && selectedBatch && (
          <BatchDetail
            batch={selectedBatch}
            status={statusFor(selectedBatch.id)}
            onBack={() => setSelectedBatch(null)}
            onEnroll={() => requestEnrollment(selectedBatch)}
            onOpenHomework={() => { setWorkspaceBatchId(selectedBatch.id); setTab("homework"); }}
            onOpenCommunity={() => { setWorkspaceBatchId(selectedBatch.id); setTab("community"); }}
            onOpenClasses={() => { setWorkspaceBatchId(selectedBatch.id); setTab("classes"); }}
            onOpenResults={() => { setWorkspaceBatchId(selectedBatch.id); setTab("testresults"); }}
          />
        )}
        {tab === "homework" && (
          <HomeworkTab
            homework={homework}
            batchId={workspaceBatchId}
            onBack={() => setTab("batches")}
          />
        )}
        {tab === "community" && (
          <CommunityTab
            batchId={workspaceBatchId}
            messages={messages}
            draft={draft}
            setDraft={setDraft}
            sendMessage={sendMessage}
            onBack={() => setTab("batches")}
          />
        )}
        {tab === "classes" && (
          <ClassesTab batchId={workspaceBatchId} classVideos={classVideos} onBack={() => setTab("batches")} />
        )}
        {tab === "testresults" && (
          <TestResultsTab batchId={workspaceBatchId} testResults={testResults} student={student} onBack={() => setTab("batches")} />
        )}
        {tab === "gallery" && (
          <GalleryTab galleryPhoto={galleryPhoto} setGalleryPhoto={setGalleryPhoto} galleryPhotos={galleryPhotos} />
        )}
        {tab === "profile" && (
          <ProfileTab
            student={student}
            enrollments={enrollments}
            payment={payment}
            onLogout={logout}
            openReceipt={setShowReceipt}
          />
        )}
        {tab === "payment" && (
          <PaymentTab payment={payment} payNow={payNow} openReceipt={setShowReceipt} onBack={() => setTab("home")} />
        )}
      </div>
      {showReceipt && (
        <ReceiptModal receipt={showReceipt} student={student} onClose={() => setShowReceipt(null)} />
      )}
      <BottomNav
        tab={
          tab === "payment"
            ? "home"
            : ["homework", "community", "classes", "testresults", "mybatches"].includes(tab)
            ? "batches"
            : tab
        }
        setTab={(t) => { setSelectedBatch(null); setWorkspaceBatchId(null); setTab(t); }}
      />
    </Frame>
  );
}

// ---------- Tab: Home ----------
function HomeTab({ student, approvedBatches, setTab, setScreen, payment, onOpenMyBatches }) {
  return (
    <div>
      <div className="px-5 pt-6 flex items-center justify-between">
        <div>
          <p className="text-stone-400 text-xs font-sans">Welcome back</p>
          <h1 className="font-serif text-xl text-stone-900">{student.name || "Student"}</h1>
        </div>
        <div className="flex items-center gap-3">
          <Bell size={19} className="text-stone-400" />
          <div className="w-9 h-9 rounded-full bg-violet-100 overflow-hidden flex items-center justify-center">
            {student.photo ? <img src={student.photo} className="w-full h-full object-cover" /> : <User size={16} className="text-violet-400" />}
          </div>
        </div>
      </div>

      {/* promo banner */}
      <div className="mx-5 mt-5 rounded-lg p-4 text-stone-50 relative overflow-hidden" style={{ background: "linear-gradient(120deg, #1c1626, #4c1d95 60%, #7C3AED)" }}>
        <p className="text-[10px] text-violet-200 font-sans">New batch forming</p>
        <p className="font-serif text-lg leading-snug mt-0.5">TOEFL &amp; IELTS batches open for enrollment</p>
        <button onClick={() => setTab("batches")} className="mt-3 text-xs bg-stone-50 text-violet-900 px-3 py-1.5 rounded-full font-sans font-medium">
          Browse batches
        </button>
      </div>

      {/* teacher/institute card */}
      <div className="mx-5 mt-5 border border-stone-200 rounded-lg p-4">
        <div className="flex gap-3">
          <div className="w-14 h-14 rounded-full bg-stone-100 overflow-hidden shrink-0">
            <img src={TEACHER_PHOTO} alt={TEACHER.name} className="w-full h-full object-cover" />
          </div>
          <div>
            <p className="font-serif text-base text-stone-900">{TEACHER.name}</p>
            <p className="text-xs text-stone-400 font-sans">{TEACHER.title}</p>
            <p className="text-xs text-violet-700 font-sans mt-1 italic">"{TEACHER.tagline}"</p>
          </div>
        </div>
        <Divider />
        <ul className="text-xs text-stone-500 font-sans space-y-1">
          {TEACHER.bio.map((b) => <li key={b}>{b}</li>)}
        </ul>
        <div className="flex items-center gap-1.5 mt-3 text-xs text-stone-400 font-sans">
          <MapPin size={13} /> Centres: {TEACHER.centres.join(" & ")}
        </div>
      </div>

      {/* quick actions */}
      <div className="grid grid-cols-2 gap-3 mx-5 mt-5">
        <QuickCard icon={CreditCard} label={`${payment.month} fee`} sub={payment.status} onClick={() => setTab("payment")} status={payment.status} />
        <QuickCard icon={BookOpen} label="My batches" sub={`${approvedBatches.length} active`} onClick={onOpenMyBatches} />
        <QuickCard icon={Images} label="Gallery" sub="Photos & results" onClick={() => setTab("gallery")} />
        <QuickCard icon={Trophy} label="Achievements" sub="ICSE / ISC 2026" onClick={() => setTab("gallery")} />
      </div>

      {/* location */}
      <div className="mx-5 mt-4 border border-stone-200 rounded-lg p-4">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-sans text-stone-700">Institute location</p>
            <p className="text-xs text-stone-400 font-sans">Krishnanagar centre, Agartala</p>
          </div>
          <a
            href={CENTRE_ADDRESS.mapsUrl}
            target="_blank" rel="noreferrer"
            className="text-xs text-violet-700 font-sans font-medium flex items-center gap-1 shrink-0"
          >
            Directions <ChevronRight size={13} />
          </a>
        </div>
        <p className="text-xs text-stone-400 font-sans mt-2 leading-relaxed">{CENTRE_ADDRESS.full}</p>
      </div>

      <div className="mx-5 mt-5 mb-8">
        <p className="text-sm font-serif text-stone-900 mb-2">Announcements</p>
        {ANNOUNCEMENTS.map((a) => (
          <div key={a.id} className="text-xs font-sans text-stone-500 border-l-2 border-violet-200 pl-3 py-1.5 mb-1.5">
            {a.text}
          </div>
        ))}
      </div>
    </div>
  );
}

function QuickCard({ icon: Icon, label, sub, onClick, status }) {
  return (
    <button onClick={onClick} className="border border-stone-200 rounded-lg p-3.5 text-left">
      <Icon size={17} className="text-violet-700 mb-2" />
      <p className="text-sm font-sans text-stone-800">{label}</p>
      {status ? <StatusPill status={sub} /> : <p className="text-xs text-stone-400 font-sans">{sub}</p>}
    </button>
  );
}

// ---------- Tab: Batches ----------
function BatchesTab({ openBatchClass, setOpenBatchClass, statusFor, setSelectedBatch }) {
  const grouped = CLASSES.map((c) => ({ cls: c, batches: CATALOG.filter((b) => b.class === c && b.kind === "academic") }));
  const examBatches = CATALOG.filter((b) => b.kind === "exam");

  return (
    <div>
      <TopBar title="Batches" />
      <div className="px-5 pb-8">
        <p className="text-stone-400 text-xs font-sans mb-4">Browse by class and board, or explore exam-prep batches.</p>

        {grouped.map((g) => (
          <div key={g.cls} className="mb-2">
            <button
              onClick={() => setOpenBatchClass(openBatchClass === g.cls ? null : g.cls)}
              className="w-full flex items-center justify-between py-3 border-b border-stone-200"
            >
              <span className="font-serif text-base text-stone-900">Class {g.cls}</span>
              <ChevronRight size={16} className={`text-stone-400 transition-transform ${openBatchClass === g.cls ? "rotate-90" : ""}`} />
            </button>
            {openBatchClass === g.cls && (
              <div className="py-2 flex flex-col gap-2">
                {g.batches.map((b) => (
                  <BatchRow key={b.id} batch={b} status={statusFor(b.id)} onClick={() => setSelectedBatch(b)} />
                ))}
              </div>
            )}
          </div>
        ))}

        <p className="font-serif text-base text-stone-900 mt-6 mb-2">Exam preparation</p>
        <div className="flex flex-col gap-2">
          {examBatches.map((b) => (
            <BatchRow key={b.id} batch={b} status={statusFor(b.id)} onClick={() => setSelectedBatch(b)} />
          ))}
        </div>
      </div>
    </div>
  );
}

function BatchRow({ batch, status, onClick }) {
  return (
    <button onClick={onClick} className="flex items-center justify-between border border-stone-200 rounded-lg px-4 py-3 text-left">
      <div>
        <p className="text-sm font-sans text-stone-800">{badgeForBatch(batch)} — {batch.name}</p>
        <p className="text-xs text-stone-400 font-sans">{batch.subject}</p>
        {batch.schedule && (
          <p className="text-[11px] text-violet-500 font-sans mt-0.5">{batch.schedule.join(" · ")}</p>
        )}
      </div>
      {status ? <StatusPill status={status} /> : <ChevronRight size={15} className="text-stone-300" />}
    </button>
  );
}

// ---------- Shown when a student has more than one enrolled batch — pick one, no full catalog ----------
function MyBatchesTab({ approvedBatches, onSelect, onBack }) {
  const batches = approvedBatches.map((id) => CATALOG.find((b) => b.id === id)).filter(Boolean);
  return (
    <div>
      <TopBar title="My batches" onBack={onBack} />
      <div className="px-5 pb-8 flex flex-col gap-2">
        {batches.map((b) => (
          <BatchRow key={b.id} batch={b} status="approved" onClick={() => onSelect(b)} />
        ))}
      </div>
    </div>
  );
}

function BatchDetail({ batch, status, onBack, onEnroll, onOpenHomework, onOpenCommunity, onOpenClasses, onOpenResults }) {
  if (status === "approved") {
    return (
      <BatchHub
        batch={batch}
        onBack={onBack}
        onOpenHomework={onOpenHomework}
        onOpenCommunity={onOpenCommunity}
        onOpenClasses={onOpenClasses}
        onOpenResults={onOpenResults}
      />
    );
  }

  return (
    <div>
      <TopBar title={badgeForBatch(batch)} onBack={onBack} />
      <div className="px-5 pb-8">
        <div className="border border-stone-200 rounded-lg p-4 mb-5">
          <p className="font-serif text-lg text-stone-900">{batch.name}</p>
          <p className="text-sm text-stone-500 font-sans mt-1">{batch.subject}</p>
          {batch.schedule && (
            <>
              <Divider />
              <p className="text-xs text-stone-400 font-sans mb-1.5">Class timing</p>
              <div className="flex flex-wrap gap-2">
                {batch.schedule.map((s) => (
                  <span key={s} className="text-xs bg-violet-50 text-violet-700 px-2 py-1 rounded-full font-sans">{s}</span>
                ))}
              </div>
            </>
          )}
          <Divider />
          <p className="text-xs text-stone-500 font-sans leading-relaxed">
            Mentored by {TEACHER.name}. Weekly live sessions, batch community for doubt-solving, and homework assigned directly to this batch.
          </p>
        </div>

        {!status && (
          <button onClick={onEnroll} className="w-full bg-violet-800 text-stone-50 py-3.5 rounded-md font-sans font-medium">
            Request enrollment
          </button>
        )}
        {status === "pending" && (
          <div className="flex items-center gap-2 text-amber-700 bg-amber-50 border border-amber-200 rounded-md p-3 text-sm font-sans">
            <Clock size={16} /> Sent to {TEACHER.name} — awaiting approval.
          </div>
        )}
        {status === "rejected" && (
          <div className="flex items-center gap-2 text-rose-700 bg-rose-50 border border-rose-200 rounded-md p-3 text-sm font-sans">
            <X size={16} /> Request declined. Contact the institute for details.
          </div>
        )}
      </div>
    </div>
  );
}

// ---------- Batch hub: shown once a student is enrolled — batch name up top, then the 4 sections ----------
function BatchHub({ batch, onBack, onOpenHomework, onOpenCommunity, onOpenClasses, onOpenResults }) {
  const items = [
    { key: "classes", label: "My Classes", icon: Video, bg: "bg-violet-100", fg: "text-violet-700", onClick: onOpenClasses },
    { key: "results", label: "Test Results", icon: Award, bg: "bg-rose-100", fg: "text-rose-700", onClick: onOpenResults },
    { key: "community", label: "Community", icon: MessageSquare, bg: "bg-blue-100", fg: "text-blue-700", onClick: onOpenCommunity },
    { key: "homework", label: "Homework", icon: FileText, bg: "bg-emerald-100", fg: "text-emerald-700", onClick: onOpenHomework },
  ];
  return (
    <div>
      <div className="bg-stone-900 px-5 pt-6 pb-7 relative">
        <button onClick={onBack} className="absolute left-5 top-6 text-stone-400">
          <ChevronLeft size={20} />
        </button>
        <p className="text-stone-400 text-xs font-sans tracking-wide text-center">YOUR BATCH</p>
        <h1 className="font-serif text-2xl text-stone-50 text-center mt-1">
          {batch.kind === "exam" ? batch.class : `${badgeForBatch(batch)} — ${batch.name}`}
        </h1>
        <p className="text-violet-300 text-xs font-sans text-center mt-1">{batch.subject}</p>
        {batch.schedule && (
          <p className="text-stone-400 text-[11px] font-sans text-center mt-1">{batch.schedule.join(" · ")}</p>
        )}
      </div>
      <div className="grid grid-cols-2 gap-x-4 gap-y-6 px-6 pt-8 pb-8">
        {items.map((it) => {
          const Icon = it.icon;
          return (
            <button key={it.key} onClick={it.onClick} className="flex flex-col items-center gap-2">
              <div className={`w-16 h-16 rounded-full flex items-center justify-center ${it.bg}`}>
                <Icon size={24} className={it.fg} />
              </div>
              <span className="text-sm font-sans text-stone-700 text-center">{it.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

