const MOCK_ROSTER_NAMES = ["Ritika Sen", "Debjit Paul", "Ananya Roy", "Sourav Nath", "Priya Das", "Kabir Chakraborty", "Ishita Bhattacharjee", "Rohan Saha"];
function mockRosterFor(batchId) {
  const seed = batchId.split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  const count = 3 + (seed % 6);
  return Array.from({ length: count }, (_, i) => MOCK_ROSTER_NAMES[(seed + i) % MOCK_ROSTER_NAMES.length]);
}

