          const Icon = it.icon;
          return (
            <button key={it.key} onClick={it.onClick} className="flex flex-col items-center gap-2">
              <div className={`w-16 h-16 rounded-full flex items-center justify-center ${it.bg}`}>
                <Icon size={24} className={it.fg} />
              </div>
              <span className="text-sm font-sans text-stone-700 text-center">{it.label}</span>
            </button>
          );
